    function saveCurrentConfig() {
      const config = {
        system_prompt: document.getElementById('sysPrompt').value,
        model: document.getElementById('modelSelect').value,
        temperature: tempSlider.value,
        top_p: topPSlider.value,
        top_k: topKSlider.value
      };

      document.querySelectorAll('.sidebar input[type="checkbox"]').forEach(cb => {
        config[cb.id] = cb.checked;
      });

      fetch('/api/config', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(config)
      });
    }

    ['sysPrompt', 'modelSelect', 'tempSlider', 'topPSlider', 'topKSlider'].forEach(id => {
      const el = document.getElementById(id);
      el.addEventListener('change', saveCurrentConfig);
      if (el.tagName === 'TEXTAREA') {
        el.addEventListener('input', saveCurrentConfig);
        el.addEventListener('blur', saveCurrentConfig);
      }
    });

    async function clearChat() {
      if (!confirm('Очистить историю чата?')) return;
      await fetch('/api/clear', { method: 'POST' });
      chatLog.innerHTML = '<div class="msg-wrapper msg-bot"><div class="msg-bubble">История очищена. О чем поговорим?</div></div>';
      if (typeof updateStats === 'function') updateStats({total_tokens: 0, prompt_tokens: 0, completion_tokens: 0, cost: 0});
    }

    async function initApp() {
      try {
        const res = await fetch('/api/state');
        const state = await res.json();

        if (state.config) {
          const c = state.config;
          document.getElementById('sysPrompt').value = c.system_prompt || '';
          document.getElementById('modelSelect').value = c.model || 'openrouter/free';
          tempSlider.value = c.temperature ?? 0.7;
          tempVal.textContent = tempSlider.value;
          topPSlider.value = c.top_p ?? 1.0;
          topPVal.textContent = topPSlider.value;
          topKSlider.value = c.top_k ?? 0;
          topKVal.textContent = topKSlider.value;

          // Restore checkboxes
          Object.keys(c).forEach(key => {
            const el = document.getElementById(key);
            if (el && el.type === 'checkbox') {
              el.checked = c[key];
            }
          });
        }

        if (state.history && state.history.length > 0) {
          chatLog.innerHTML = '';
          state.history.forEach(m => {
            const isBot = m.role === 'assistant';
            const meta = (isBot && m.model) ? { model: m.model, time: m.time, usage: m.usage } : null;
            addMessage(isBot ? 'bot' : 'user', m.content, meta);
          });
        }
        if (typeof updateStats === 'function' && state.stats) updateStats(state.stats);
      } catch (e) {
        console.error("Failed to load state", e);
      }
    }

    {{EXTRA_SCRIPTS}}

    window.addEventListener('DOMContentLoaded', initApp);
  </script>
</body>
</html>"""
    return html.replace("{{TITLE}}", title).replace("{{EXTRA_SIDEBAR_HTML}}", extra_sidebar_html).replace("{{EXTRA_SCRIPTS}}", extra_scripts)

class DocumentIndexer:
    def __init__(self, root_dir: Path = ROOT_DIR):
        self.root_dir = root_dir
        self.documents: List[Dict[str, Any]] = []
        self.chunks: List[Dict[str, Any]] = []

    def load_corpus(self) -> List[Dict[str, Any]]:
        """Загружает корпус документов проекта (.md и .py файлы)."""
        docs = []
        for path in self.root_dir.rglob("*"):
            if path.is_file() and path.suffix in [".md", ".py"] and ".git" not in path.parts and ".venv" not in path.parts:
                try:
                    content = path.read_text(encoding="utf-8")
                    if len(content.strip()) > 50:
                        docs.append({
                            "source": str(path.relative_to(self.root_dir)),
                            "title": path.name,
                            "type": path.suffix.lstrip("."),
                            "content": content
                        })
                except Exception:
                    pass
        self.documents = docs
        return docs

    def chunk_fixed_size(self, chunk_size: int = 600, overlap: int = 60) -> List[Dict[str, Any]]:
        """Стратегия 1: Разбиение по фиксированному размеру символов с перекрытием."""
        fixed_chunks = []
        chunk_counter = 1

        for doc in self.documents:
            text = doc["content"]
            source = doc["source"]
            title = doc["title"]

            length = len(text)
            start = 0
            while start < length:
                end = min(start + chunk_size, length)
                chunk_text = text[start:end]

                chunk = {
                    "chunk_id": f"fix_{chunk_counter:04d}",
                    "source": source,
                    "title_or_file": title,
                    "section": f"Chars {start}-{end}",
                    "strategy": "fixed_size",
                    "text": chunk_text,
                    "word_count": len(chunk_text.split())
                }
                fixed_chunks.append(chunk)
                chunk_counter += 1
                start += (chunk_size - overlap)

        return fixed_chunks

    def chunk_structural(self) -> List[Dict[str, Any]]:
        """Стратегия 2: Структурное/семантическое разбиение (по заголовкам Markdown и классам/функциям Python)."""
        struct_chunks = []
        chunk_counter = 1

        for doc in self.documents:
            text = doc["content"]
            source = doc["source"]
            title = doc["title"]
            doc_type = doc["type"]

            if doc_type == "md":
                # Разбиваем по заголовкам Markdown (#, ##, ###)
                sections = re.split(r'(?m)^(#{1,3}\s+.+)', text)
                current_section = "Introduction"
                current_text = ""

                for part in sections:
                    part_stripped = part.strip()
                    if part_stripped.startswith("#"):
                        if current_text.strip():
                            chunk = {
                                "chunk_id": f"str_{chunk_counter:04d}",
                                "source": source,
                                "title_or_file": title,
                                "section": current_section,
                                "strategy": "structural",
                                "text": current_text.strip(),
                                "word_count": len(current_text.split())
                            }
                            struct_chunks.append(chunk)
                            chunk_counter += 1
                        current_section = part_stripped.lstrip("#").strip()
                        current_text = ""
                    else:
                        current_text += part + "\n"

                if current_text.strip():
                    chunk = {
                        "chunk_id": f"str_{chunk_counter:04d}",
                        "source": source,
                        "title_or_file": title,
                        "section": current_section,
                        "strategy": "structural",
                        "text": current_text.strip(),
                        "word_count": len(current_text.split())
                    }
                    struct_chunks.append(chunk)
                    chunk_counter += 1

            elif doc_type == "py":
                # Разбиваем по функциям def и классам class в Python
                lines = text.splitlines()
                current_section = "Module Header"
                current_lines = []

                for line in lines:
                    if line.startswith("def ") or line.startswith("class "):
                        if current_lines:
                            block_text = "\n".join(current_lines)
                            if block_text.strip():
                                chunk = {
                                    "chunk_id": f"str_{chunk_counter:04d}",
                                    "source": source,
                                    "title_or_file": title,
                                    "section": current_section,
                                    "strategy": "structural",
                                    "text": block_text.strip(),
                                    "word_count": len(block_text.split())
                                }
                                struct_chunks.append(chunk)
                                chunk_counter += 1
                        current_section = line.strip()
                        current_lines = [line]
                    else:
                        current_lines.append(line)

                if current_lines:
                    block_text = "\n".join(current_lines)
                    if block_text.strip():
                        chunk = {
                            "chunk_id": f"str_{chunk_counter:04d}",
                            "source": source,
                            "title_or_file": title,
                            "section": current_section,
                            "strategy": "structural",
                            "text": block_text.strip(),
                            "word_count": len(block_text.split())
                        }
                        struct_chunks.append(chunk)
                        chunk_counter += 1

        return struct_chunks

    def build_index(self) -> Dict[str, Any]:
        """Строит полный индекс, применяя обе стратегии chunking."""
        self.load_corpus()
        fix_chunks = self.chunk_fixed_size()
        str_chunks = self.chunk_structural()
        self.chunks = fix_chunks + str_chunks

        index_data = {
            "total_documents": len(self.documents),
            "total_chunks": len(self.chunks),
            "strategies": {
                "fixed_size": {
                    "count": len(fix_chunks),
                    "avg_word_count": sum(c["word_count"] for c in fix_chunks) / max(1, len(fix_chunks))
                },
                "structural": {
                    "count": len(str_chunks),
                    "avg_word_count": sum(c["word_count"] for c in str_chunks) / max(1, len(str_chunks))
                }
            },
            "chunks": self.chunks
        }

        INDEX_FILE.write_text(json.dumps(index_data, ensure_ascii=False, indent=2), encoding="utf-8")
        return index_data

    def search(self, query: str, strategy: str = "all") -> List[Dict[str, Any]]:
        """Семантический/текстовый поиск по индексу с учетом стратегии."""
        if not INDEX_FILE.exists():
            self.build_index()

        try:
            data = json.loads(INDEX_FILE.read_text(encoding="utf-8"))
            all_chunks = data.get("chunks", [])
        except Exception:
            all_chunks = self.chunks

        q_words = set(query.lower().split())
        scored = []

        for c in all_chunks:
            if strategy != "all" and c.get("strategy") != strategy:
                continue
            text_lower = c["text"].lower()
            # Простейший подсчет совпадений слов (TF-IDF симуляция)
            score = sum(1 for w in q_words if w in text_lower)
            if score > 0:
                scored.append((score, c))

        scored.sort(key=lambda x: x[0], reverse=True)
        return [item[1] for item in scored[:10]]

    def compare_strategies(self) -> Dict[str, Any]:
        """Возвращает детальный отчет сравнения Fixed Size и Structural стратегий."""
        if not INDEX_FILE.exists():
            self.build_index()

        data = json.loads(INDEX_FILE.read_text(encoding="utf-8"))
        fix_c = [c for c in data["chunks"] if c["strategy"] == "fixed_size"]
        str_c = [c for c in data["chunks"] if c["strategy"] == "structural"]

        def stats(lst):
            if not lst:
                return {"count": 0, "avg_words": 0, "min_words": 0, "max_words": 0}
            counts = [c["word_count"] for c in lst]
            return {
                "count": len(lst),
                "avg_words": round(sum(counts) / len(counts), 1),
                "min_words": min(counts),
                "max_words": max(counts)
            }

        return {
            "total_documents_indexed": data["total_documents"],
            "comparison": {
                "fixed_size_strategy": {
                    "description": "Разбиение блоков текста строго по фиксированному числу символов с перекрытием (overlap).",
                    "metrics": stats(fix_c),
                    "pros": ["Равномерный размер чанков", "Простота реализации"],
                    "cons": ["Может разрывать предложения и смысловые блоки посередине"]
                },
                "structural_strategy": {
                    "description": "Интеллектуальное разбиение по границам структуры документов (заголовки Markdown, функции и классы Python).",
                    "metrics": stats(str_c),
                    "pros": ["Сохраняет целостность логических блоков и функций", "Лучший контекст для RAG"],
                    "cons": ["Разбросанный размер чанков (от коротких до длинных методов)"]
                }
            }
        }

if __name__ == "__main__":
    indexer = DocumentIndexer()
    res = indexer.build_index()
    print(f"Indexed {res['total_documents']} documents into {res['total_chunks']} chunks.")

def _run_git_cmd(args: List[str]) -> Tuple[int, str, str]:
    """Выполняет команду git в директории проекта."""
    try:
        res = subprocess.run(
            ["git"] + args,
            cwd=str(ROOT_DIR),
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True
        )
        return res.returncode, res.stdout.strip(), res.stderr.strip()
    except Exception as e:
        return 1, "", str(e)

def _load_state() -> dict:
    if STATE_FILE.exists():
        try:
            return json.loads(STATE_FILE.read_text(encoding="utf-8"))
        except Exception:
            pass
    return {"student": "Студент AI Advent", "assignments": {}}

def _save_state(state: dict):
    try:
        STATE_FILE.write_text(json.dumps(state, ensure_ascii=False, indent=2), encoding="utf-8")
    except Exception as e:
        sys.stderr.write(f"Error saving state: {e}\n")

def git_status_check() -> str:
    """Проверяет текущую ветку Git, статус измененных файлов и готовность к коммиту."""
    code_b, current_branch, err_b = _run_git_cmd(["branch", "--show-current"])
    if code_b != 0 or not current_branch:
        code_b2, current_branch, _ = _run_git_cmd(["rev-parse", "--abbrev-ref", "HEAD"])
        if code_b2 != 0:
            current_branch = "unknown"

    code_s, status_out, err_s = _run_git_cmd(["status", "--porcelain"])

    modified_files = []
    if status_out:
        for line in status_out.splitlines():
            line = line.strip()
            if line:
                modified_files.append(line)

    return json.dumps({
        "current_branch": current_branch,
        "has_uncommitted_changes": len(modified_files) > 0,
        "modified_files_count": len(modified_files),
        "modified_files": modified_files[:20],
        "message": f"Текущая ветка: {current_branch}. Измененных файлов: {len(modified_files)}"
    }, ensure_ascii=False, indent=2)

def git_commit_and_push(branch_name: str, target_files: Union[List[str], str], commit_message: str = "") -> str:
    """Выполняет ТОЧЕЧНЫЙ git add выбранных файлов, создает коммит и делает настоящий git push на GitHub."""
    target_branch = branch_name.strip() or "main"
    msg = commit_message.strip() or f"AI Advent submission for branch {target_branch}"

    # Парсим список файлов (может быть передан массивом или строкой через запятую)
    if isinstance(target_files, str):
        files_list = [f.strip() for f in target_files.split(",") if f.strip()]
    else:
        files_list = [str(f).strip() for f in target_files if str(f).strip()]

    if not files_list:
        files_list = ["day17.py", "mcp_server_git.py", "README.md"]

    log_steps = []

    # 1. Переключаем / создаем целевую ветку
    c_code, c_out, c_err = _run_git_cmd(["checkout", "-B", target_branch])
    log_steps.append(f"git checkout -B {target_branch}: {c_out or c_err}")

    # 2. ТОЧЕЧНЫЙ add только выбранных файлов (БЕЗ git add .)
    staged_files = []
    for f_path in files_list:
        full_p = ROOT_DIR / f_path
        if full_p.exists():
            a_code, a_out, a_err = _run_git_cmd(["add", f_path])
            if a_code == 0:
                staged_files.append(f_path)
                log_steps.append(f"git add {f_path}: ok")
            else:
                log_steps.append(f"git add {f_path} warning: {a_err}")
        else:
            log_steps.append(f"file not found for git add: {f_path}")

    # 3. Проверяем, появились ли скоммичиваемые изменения в индексе
    code_s, status_staged, _ = _run_git_cmd(["status", "--porcelain"])

    commit_created = False
    if status_staged:
        m_code, m_out, m_err = _run_git_cmd(["commit", "-m", msg])
        if m_code == 0:
            commit_created = True
            log_steps.append(f"git commit -m '{msg}': {m_out or m_err}")
        else:
            log_steps.append(f"git commit warning: {m_err or m_out}")
    else:
        log_steps.append("git commit: Нечего коммитить (выбранные файлы уже зафиксированы)")

    # 4. Настоящий push на GitHub
    p_code, p_out, p_err = _run_git_cmd(["push", "-u", "origin", target_branch])
    push_msg = p_out or p_err or "Up to date"
    log_steps.append(f"git push -u origin {target_branch}: {push_msg}")

    if commit_created:
        msg_result = f"✅ Точечно скоммичено файлов ({len(staged_files)}) и отправлено в ветку '{target_branch}' на GitHub!"
    elif p_code == 0:
        msg_result = f"ℹ️ Ветка '{target_branch}' синхронизирована с GitHub ({push_msg}). Выбранные файлы не требовали нового коммита."
    else:
        msg_result = f"⚠️ Ветка '{target_branch}': git push вернул {push_msg}"

    return json.dumps({
        "status": "success" if p_code == 0 else "push_warning",
        "branch": target_branch,
        "staged_files": staged_files,
        "commit_created": commit_created,
        "git_push_output": push_msg,
        "log_steps": log_steps,
        "message": msg_result
    }, ensure_ascii=False, indent=2)

def format_submission_comments(day_number: str, branch_name: str, code_link: str, video_link: str = "") -> str:
    """Формирует два точных комментария сдачи для Google Таблицы."""
    day_key = str(day_number).strip()
    branch = branch_name.strip() or f"day{day_key}"

    code_url = code_link.strip() or f"https://github.com/user/ai_advent_1/blob/{branch}/day{day_key}.py"
    video_url = video_link.strip() or "https://youtu.be/..."

    code_comment = f"код (ветка {branch}): {code_url}"
    video_comment = f"видео: {video_url}"

    state = _load_state()
    assignments = state.setdefault("assignments", {})
    day_info = assignments.setdefault(day_key, {})

    day_info["branch_name"] = branch
    day_info["code_link"] = code_url
    day_info["video_link"] = video_url
    day_info["code_comment"] = code_comment
    day_info["video_comment"] = video_comment
    day_info["updated_at"] = time.strftime("%Y-%m-%d %H:%M:%S")
    day_info["status"] = "fully_submitted" if (video_url and "http" in video_url) else "code_submitted"
    _save_state(state)

    return json.dumps({
        "status": "success",
        "day": day_key,
        "branch": branch,
        "code_comment": code_comment,
        "video_comment": video_comment,
        "message": "✅ Сформированы 2 комментария для Google Таблицы с кнопками скопировать!"
    }, ensure_ascii=False, indent=2)

